try{
 $def=$svc.NewTask(0);$def.RegistrationInfo.Description='r15 actual-supervisor WMI-free canary; no training';$def.Principal.UserId=[Security.Principal.WindowsIdentity]::GetCurrent().Name;$def.Principal.LogonType=3;$def.Settings.MultipleInstances=2;$def.Settings.RestartCount=0;$def.Settings.ExecutionTimeLimit='PT0S';$def.Settings.AllowDemandStart=$true;$action=$def.Actions.Create(0);$action.Path="$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe";$action.Arguments=$args;$action.WorkingDirectory=Split-Path -Parent $supervisor
 $task=$folder.RegisterTaskDefinition($taskName,$def,2,$null,$null,3,$null);$registered=$true;if([string]$task.Definition.Actions.Item(1).Arguments-cne$args){throw 'persisted canary action changed'};$instance=$task.RunEx($null,0,0,$null);$deadline=(Get-Date).AddSeconds($TimeoutSeconds);while(!(Test-Path -LiteralPath $handshake)-and(Get-Date)-lt$deadline){Start-Sleep -Milliseconds 250}
 if(!(Test-Path -LiteralPath $handshake)){throw 'actual r15 supervisor canary handshake timed out'};$h=Get-Content -LiteralPath $handshake -Raw|ConvertFrom-Json;$events=@(Get-Content -LiteralPath $preflight|%{$_|ConvertFrom-Json})
