}finally{if($instance){try{if([int]$instance.State-eq4){$instance.Stop()}}catch{}};if($registered){try{$folder.DeleteTask($taskName,0)}catch{}};if(@($production|?{Test-Path -LiteralPath $_}).Count){throw 'r15 production artifact appeared after canary'}}
